        var state=computer.state||'unavailable',ready=state==='running',user=computer.control==='user';
        status.textContent=state==='starting'?'Starting':state.slice(0,1).toUpperCase()+state.slice(1)+(ready&&user?' · You have control':'');
        detail.textContent=computer.error||computer.handoff&&computer.handoff.reason|| (computer.executionLocation==='host'?'Last activity used this computer.':'');detail.hidden=!detail.textContent;
        buttons.forEach(function(button){var action=button.dataset.computerAction;button.hidden=action==='open'?!ready:action==='start'?!['stopped','sleeping','unavailable'].includes(state):action==='stop'?state==='stopped':action==='take-control'?!ready||user:!ready||!user;button.disabled=false;});
