        try{await api(url(agentId),{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:action})});if(active()&&card.isConnected)await refresh();}
        catch(error){if(active()&&card.isConnected){companyError(error);await refresh();}}
